CREATE TABLE MAP.DUPLICATE_NUMBER
NOLOGGING
AS
SELECT MOBILE_NUMBER, ID AS ID
FROM MAP.WALLET_USER
WHERE 1 = 2;

INSERT /*+ APPEND */
INTO MAP.DUPLICATE_NUMBER
SELECT MOBILE_NUMBER,ID FROM (SELECT ID,MOBILE_NUMBER,
rank() OVER (PARTITION BY MOBILE_NUMBER ORDER BY (CASE WHEN STATUS='ACTIVE' THEN CURRENT_TIMESTAMP ELSE UPDATED END) DESC,ID DESC)   as rnk FROM MAP.WALLET_USER 
WHERE STATUS IN ('REGISTERED','REGISTRATION_EXPIRED','ACTIVE')) WHERE rnk>1;

COMMIT;

DELETE FROM MAP.AUTHENTICATION_CODE WHERE USER_ID IN (SELECT ID FROM MAP.DUPLICATE_NUMBER);
UPDATE MAP.WALLET_USER SET STATUS = 'DELETED' WHERE ID IN (SELECT ID FROM MAP.DUPLICATE_NUMBER);

CREATE UNIQUE INDEX "MAP"."IDX_UNQ_MOBILE_NUMBER" ON "MAP"."WALLET_USER" (CASE "STATUS" WHEN 'DELETED' THEN NULL ELSE MOBILE_NUMBER END) ;
COMMIT;

DROP TABLE MAP.DUPLICATE_NUMBER;
